"""Tests for scripts/parse_typos_transcripts_report.py."""

import json
import subprocess
import sys
from pathlib import Path


def _run_parse_script(
    input_path: Path,
    output_path: Path,
    no_occurrences: bool = False,
) -> dict:
    """Run parse_typos_transcripts_report.py; return parsed output JSON."""
    cmd = [
        sys.executable,
        "scripts/parse_typos_transcripts_report.py",
        "-i",
        str(input_path),
        "-o",
        str(output_path),
    ]
    if no_occurrences:
        cmd.append("--no-occurrences")
    result = subprocess.run(  # noqa: S603
        cmd,
        capture_output=True,
        text=True,
        check=True,
        cwd=Path(__file__).resolve().parents[1],
    )
    assert result.returncode == 0, (result.stdout, result.stderr)
    return json.loads(output_path.read_text())


def test_parses_valid_json_lines(tmp_path: Path) -> None:
    """Valid typos JSON lines are parsed and deduped by (typo, correction)."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"typo","path":"a.json","line_num":1,"byte_offset":0,"typo":"expression","corrections":["expression"]}\n'
        '{"type":"typo","path":"b.json","line_num":2,"byte_offset":0,"typo":"expression","corrections":["expression"]}\n'
    )
    out = tmp_path / "candidates.json"
    data = _run_parse_script(report, out)
    assert data["total_unique_pairs"] == 1
    assert len(data["candidates"]) == 1
    assert data["candidates"][0]["typo"] == "expression"
    assert data["candidates"][0]["correction"] == "expression"
    assert data["candidates"][0]["count"] == 2
    assert len(data["candidates"][0]["occurrences"]) == 2


def test_skips_non_typo_lines(tmp_path: Path) -> None:
    """Lines with type != typo or missing fields are skipped."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"other"}\n'
        '{"type":"typo","path":"a.json","line_num":1,"typo":"x","corrections":["y"]}\n'
    )
