def test_uses_first_correction(tmp_path: Path) -> None:
    """When corrections has multiple suggestions, first is used."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"typo","path":"a.json","line_num":1,"typo":"the","corrections":["the","tea"]}\n'
    )
    out = tmp_path / "candidates.json"
    data = _run_parse_script(report, out)
    assert data["candidates"][0]["correction"] == "the"


def test_no_occurrences_omits_occurrences_list(tmp_path: Path) -> None:
    """--no-occurrences omits occurrences from output but count is correct."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"typo","path":"a.json","line_num":1,"typo":"x","corrections":["y"]}\n'
        '{"type":"typo","path":"a.json","line_num":2,"typo":"x","corrections":["y"]}\n'
    )
    out = tmp_path / "candidates.json"
    data = _run_parse_script(report, out, no_occurrences=True)
    assert data["candidates"][0]["count"] == 2
    assert "occurrences" not in data["candidates"][0]


def test_occurrences_truncated_when_over_100(tmp_path: Path) -> None:
    """When occurrences > 100, list is truncated and occurrences_truncated is True."""
    report = tmp_path / "report.json"
    lines = [
        json.dumps(
            {
                "type": "typo",
                "path": "f.json",
                "line_num": i,
                "byte_offset": 0,
                "typo": "x",
                "corrections": ["y"],
            }
        )
        for i in range(150)
    ]
    report.write_text("\n".join(lines))
    out = tmp_path / "candidates.json"
    data = _run_parse_script(report, out)
    assert data["candidates"][0]["count"] == 150
    assert len(data["candidates"][0]["occurrences"]) == 100
    assert data["candidates"][0]["occurrences_truncated"] is True


def test_output_dir_created(tmp_path: Path) -> None:
    """Output directory is created if it does not exist."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"typo","path":"a.json","line_num":1,"typo":"x","corrections":["y"]}\n'
    )
    out = tmp_path / "subdir" / "candidates.json"
